    public void UpdateAuthorityCheckpoint(
        long clientId,
        TallyCompanyInfo company,
        TallyVoucherChangeMarker marker,
        string status,
        string error = "")
    {
        using var connection = OpenConnection();
        using var command = connection.CreateCommand();
        command.CommandText =
            """
